style.css:
/* CR7 — The 2008 Era | WallpaperFlare */

:root {
  /* customize these colors */
  --my-bg: #090a0d;
  --my-panel: #15171c;
  --my-red: #da202c;
  --my-gold: #c9a45c;
  --my-text: #f5f5f5;
  --my-muted: #969ba5;
}

/* dark stadium atmosphere */
html,
body {
  background: var(--my-bg) !important;
  color: var(--my-text) !important;
  font-family: "Segoe UI", Arial, sans-serif !important;
}

/* legendary red headings */
h1, h2, h3, h4 {
  color: var(--my-red) !important;
  letter-spacing: 1px !important;
}

/* links */
a {
  color: var(--my-gold) !important;
}

a:hover {
  color: var(--my-red) !important;
}

/* wallpaper presentation */
img {
  border-radius: 8px !important;
}

/* panels */
main,
section,
article {
  background-color: var(--my-bg) !important;
  color: var(--my-text) !important;
}

/* buttons */
button,
input,
select {
  background: var(--my-panel) !important;
  color: white !important;
  border: 1px solid #383b42 !important;
  border-radius: 6px !important;
}

/* scrollbar */
* {
  scrollbar-color: var(--my-red) var(--my-bg);
}

/* selected text */
::selection {
  background: var(--my-red) !important;
  color: white !important;
}
